    @Test
    @Tag("neuro-integration")
    @DisplayName("[I-AC-6-c392e87c] 1 distinct SKU with high quantity is accepted (not about distinct SKU count)")
    void test_I_AC_6_c392e87c() throws Exception {
        HttpResponse<String> response0 = send("POST", "/api/orders/total", "{\"id\":\"order-single-sku\",\"customerId\":\"cust-4\",\"customerTier\":\"STANDARD\",\"items\":[{\"sku\":\"SKU-ONLY\",\"unitPrice\":\"10.00\",\"quantity\":100}]}", "application/json");
        assertThat(response0.statusCode()).as("POST /api/orders/total").isEqualTo(200);
        assertNotEmpty(com.jayway.jsonpath.JsonPath.<Object>read(response0.body(), "$.total"), "total");
    }

    private static void assertNotEmpty(Object value, String path) {
        assertThat(value).as(path).isNotNull();
        if (value instanceof CharSequence text) {
            assertThat(text.toString()).as(path).isNotBlank();
        }
        if (value instanceof java.util.Collection<?> items) {
            assertThat(items).as(path).isNotEmpty();
        }
    }
